	public InspectionPlan getInspectionPlan( InspectionPlanFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "InspectionPlanFetchOneSummary arg cannot be null" );

		InspectionPlan entity = null;
		UUID id = summary.getInspectionPlanId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a InspectionPlan using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


